import sys
from collections import deque
from functools import lru_cache

n = int(sys.stdin.read().split()[0])

if n <= 1500:
    LIM = 4096
    dist = {n: 0}
    q = deque([n])
    while q:
        x = q.popleft()
        if x == 0:
            break
        k = 1
        while k <= LIM:
            for y in (x + k, x - k):
                if -2 * LIM <= y <= 2 * LIM and y not in dist:
                    dist[y] = dist[x] + 1
                    q.append(y)
            k *= 2
    print(dist[0])
else:
    sys.setrecursionlimit(10000)

    @lru_cache(maxsize=None)
    def f(m):
        if m == 0:
            return 0
        if m == 1:
            return 1
        if m % 2 == 0:
            return f(m // 2)
        return 1 + min(f((m - 1) // 2), f((m + 1) // 2))

    print(f(n))

